endpoints: (builder) => ({
  // 1. The Query fetches the list, and slaps a 'Post' label on the cache
  getPosts: builder.query({
    query: () => '/posts',
    providesTags: ['Post'],
  }),

  // 2. The Mutation adds a new post.
  addPost: builder.mutation({
    query: (body) => ({ url: '/posts', method: 'POST', body }),
    // 3. When this succeeds, it destroys the 'Post' label.
    // RTK Query immediately forces getPosts() to run again to get the new list!
    invalidatesTags: ['Post'],
  }),
})
